{
  "project": "cadi-alfa",
  "module": "bucle_jornada",
  "description": "Módulo M5: Bucle de Jornada. Orquestra el ciclo completo de una jornada: avance de tiempo (M1), comprobación de pivotes (M1), generación de eventos (M4), resolución de eventos (M7), aplicación de decaimientos (M3), comprobación de umbrales (M3) y cierre de jornada (M5).",
  "functions": [
    {
      "name": "ejecutar_bucle_jornada",
      "signature": "pub fn ejecutar_bucle_jornada(game: &mut GameState, plantillas: &[EventTemplate]) -> Result<(), String>",
      "description": "Ejecuta la secuencia completa de una jornada.",
      "examples": [
        "ejecutar_bucle_jornada(&mut game, &plantillas).unwrap();"
      ]
    },
    {
      "name": "avanzar_tiempo",
      "signature": "pub fn avanzar_tiempo(game: &mut GameState)",
      "description": "Avanza el tiempo en una jornada."
    },
    {
      "name": "comprobar_pivotes",
      "signature": "pub fn comprobar_pivotes(game: &mut GameState)",
      "description": "Comprueba pivotes históricos y aplica mutaciones."
    },
    {
      "name": "aplicar_decaimientos",
      "signature": "pub fn aplicar_decaimientos(game: &mut GameState)",
      "description": "Aplica decaimiento pasivo a medidores."
    },
    {
      "name": "comprobar_umbrales",
      "signature": "pub fn comprobar_umbrales(game: &mut GameState) -> Vec<String>",
      "description": "Comprueba si medidores cruzaron umbrales.",
      "examples": [
        "let alertas = comprobar_umbrales(&mut game);"
      ]
    }
  ],
  "tests": [
    "#[test] fn test_ejecutar_bucle_jornada_incrementa_jornada() { use crate::game_state::GameState; use crate::generador_eventos::EventTemplate; let mut game = GameState::new(); let plantillas = vec![]; ejecutar_bucle_jornada(&mut game, &plantillas).unwrap(); assert_eq!(game.world.time.jornada_absoluta, 1); }",
    "#[test] fn test_avanzar_tiempo_incrementa_jornada() { use crate::game_state::GameState; let mut game = GameState::new(); avanzar_tiempo(&mut game); assert_eq!(game.world.time.jornada_absoluta, 1); }",
    "#[test] fn test_comprobar_umbrales_detecta_medidor_bajo() { use crate::game_state::GameState; use crate::player_state::{PlayerState, PlayerMeters}; let mut game = GameState { player: PlayerState { meters: PlayerMeters { influencia_valor: 10, influencia_umbral_bajo: 20, ..Default::default() }, ..Default::default() }, ..Default::default() }; let alertas = comprobar_umbrales(&mut game); assert!(alertas.contains(&String::from(\"med_influencia bajo umbral\"))); }"
  ],
  "dependencies": [
    "serde"
  ],
  "notes": "Ubicar en /media/alvaro/service/project-stack/cadi-alfa/repo/rust/crates/game_core/src/bucle_jornada.rs. Importar: use crate::game_state::GameState; use crate::generador_eventos::{EventTemplate, generar_eventos_jornada}; use crate::meter_delta_applier::aplicar_delta; use crate::cooldown_tick::tick_cooldowns; use crate::close_jornada::cerrar_jornada. No implementar pivotes aún."
}
